<script>
async function copyStudioValue(id,button){const field=document.getElementById(id);if(!field||!field.value)return;const original=button.innerHTML;try{await navigator.clipboard.writeText(field.value);}catch(_){field.select();document.execCommand('copy');}button.innerHTML='<i class="fas fa-check"></i><span>Copied</span>';window.setTimeout(()=>button.innerHTML=original,1400);}
function toggleStudioKey(button){const field=document.getElementById('stream-key-value');if(!field)return;const showing=field.type==='password';field.type=showing?'text':'password';button.innerHTML=showing?'<i class="far fa-eye-slash"></i><span>Hide</span>':'<i class="far fa-eye"></i><span>Show</span>';}
document.addEventListener('DOMContentLoaded',()=>{const provider=document.getElementById('live-provider');const urlFields=document.getElementById('live-watch-url');const manualToggle=document.getElementById('manual-live-toggle');const autoStatus=document.getElementById('auto-live-status');const serverNotice=document.getElementById('server-live-notice');const updateProvider=()=>{const server=provider.value==='church_server';urlFields.classList.toggle('hidden',server);manualToggle.classList.toggle('hidden',server);autoStatus.classList.toggle('hidden',!server);serverNotice.classList.toggle('hidden',!server);};provider.addEventListener('change',updateProvider);updateProvider();
    const statusLabel=document.getElementById('studio-status-label');const statusMessage=document.getElementById('studio-status-message');const statusBox=document.querySelector('.studio-status');const statusTime=document.querySelector('.studio-status-live-time');const statusUrl=@json(url('/api/streaming/public-status'));
    window.setInterval(async()=>{try{const response=await fetch(statusUrl,{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)return;const data=await response.json();const live=Boolean(data.is_live);const current=statusBox.classList.contains('is-live');if(live===current)return;statusBox.classList.toggle('is-live',live);statusLabel.textContent=live?'YOUR CHURCH IS LIVE':'STREAM IS OFF AIR';statusMessage.textContent=live?'Your broadcast is reaching the public website now.':'Your broadcast has ended. The home page welcome slides are showing again.';statusTime.textContent=live?'Connected just now':'Ready when you are';}catch(_){}}
    ,10000);
});
</script>
@endpush
